    if len(l) == 0:
        raise ValueError("The list must contain at least one element.")

    l_sorted = sorted(l)
    n = len(l_sorted)
    mid = n // 2

    if n % 2 == 1:
        return l_sorted[mid]
    else:
        return (l_sorted[mid - 1] + l_sorted[mid]) / 2.0

